"""Generate self-contained, mobile-friendly offline report. No external JS or requests."""
import json
def render(data,path):
    payload=json.dumps(data,ensure_ascii=False,separators=(",",":")).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026")
    template=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>行业热点雷达 V1.1</title>
<style>
:root{color-scheme:light dark;--bg:#f5f7fa;--panel:#fff;--text:#182735;--muted:#617080;--line:#dce3ea;--accent:#276c8a}
@media(prefers-color-scheme:dark){:root{--bg:#121820;--panel:#1b2430;--text:#e7eef4;--muted:#abb8c7;--line:#354353;--accent:#8ac9e2}}
*{box-sizing:border-box}body{font:14px system-ui,sans-serif;background:var(--bg);color:var(--text);max-width:1120px;margin:auto;padding:16px}h1{font-size:24px;margin:8px 0}h2{font-size:18px}h3{font-size:16px}p{line-height:1.5}.sub{color:var(--muted);font-size:12px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px;margin:12px 0}select,input,button{font:inherit;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--text)}button{cursor:pointer}button.active{border-color:var(--accent);color:var(--accent);font-weight:700}.bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:8px}.item{border:1px solid var(--line);border-radius:8px;padding:10px;background:var(--panel);text-align:left}.item strong{display:block;margin:4px 0;font-size:15px}.metric{font-size:20px;font-weight:700}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{border-bottom:1px solid var(--line);padding:9px;text-align:left;white-space:nowrap}th{font-size:12px;color:var(--muted)}td:first-child{position:sticky;left:0;background:var(--panel)}.tag{display:inline-block;border:1px solid var(--line);border-radius:4px;padding:2px 5px;font-size:11px;margin:2px}.up{color:#c55757}.down{color:#25865e}dialog{background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:12px;width:min(95vw,740px);max-height:90vh;overflow:auto;padding:16px}dialog::backdrop{background:#0008}svg{max-width:100%;height:auto}.empty{padding:20px;color:var(--muted)}#close{float:right}
</style><body><h1>行业热点雷达 V1.1</h1><div id="asof" class="sub"></div><p class="sub">收盘观察 · 非买卖建议 · 关注度为成交额占申万一级合计的近5日均值 / 此前20日均值，不是净资金流入。</p>
<div class="panel"><div class="bar"><button id="l1">申万一级</button><button id="l2">申万二级</button><select id="sort"><option value="rank">相对强度</option><option value="attention">成交关注度</option><option value="move">排名跃升</option><option value="breadth">扩散增强</option></select><select id="flag"><option value="">全部观察</option><option>量价前兆</option><option>关注度异动</option><option>排名跃升</option><option>扩散增强</option><option>扩散收窄</option><option>放量下跌</option><option>放量相对弱势</option></select><select id="stage"><option value="">全部阶段</option><option>启动</option><option>主升</option><option>潜伏</option><option>过热</option><option>退潮</option><option>普通</option><option>证据不足</option></select><input id="query" placeholder="搜索行业名称或代码"></div><p id="health" class="sub"></p></div>
<div id="summary"></div><section class="panel"><h2>行业全景</h2><p class="sub">点击行业名称查看20日变化与个股观察名单。广度变化为相同有效成分的近5日上涨比例减此前5日上涨比例。</p><div id="table" class="scroll"></div></section>
<dialog id="detail"><button id="close">关闭</button><div id="detailbody"></div></dialog>
<script type="application/json" id="data">__PAYLOAD__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let level='L2';
function el(tag,t,cls){const e=document.createElement(tag);if(t!==undefined)e.textContent=t;if(cls)e.className=cls;return e}
const pct=(x,sign=true)=>x==null?'—':(sign&&x>0?'+':'')+(x*100).toFixed(2)+'%';const pp=x=>x==null?'—':(x>0?'+':'')+(x*100).toFixed(1)+' pp';const ratio=x=>x==null?'—':x.toFixed(2)+'×';const ord=x=>x==null?-Infinity:x;
function td(tr,t,cls){tr.append(el('td',t,cls))}
function makeTable(head){const t=el('table'),h=el('thead'),r=el('tr');head.forEach(x=>r.append(el('th',x)));h.append(r);t.append(h);const b=el('tbody');t.append(b);return [t,b]}
function detail(x){const b=$('detailbody');b.replaceChildren(el('h2',x.name+' · '+x.stage),el('p',x.flags.join(' · ')||'暂无观察标记','sub'));const h=x.breadth;
b.append(el('p','5日 '+pct(x.r5)+' · 20日 '+pct(x.r20)+' · 关注度 '+ratio(x.attention)+' · 广度变化 '+pp(h?.breadth_change)));
b.append(el('h3','20日行业强度排名分位（越高越强）'));const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 320 120');const arr=x.timeline;
let path='',ongoing=false;arr.forEach((v,i)=>{if(v.rank_pct==null){ongoing=false;return}const xx=10+i*300/Math.max(1,arr.length-1),yy=10+v.rank_pct*90;path+=(ongoing?' L':' M')+xx+' '+yy;ongoing=true});const p=document.createElementNS(ns,'path');p.setAttribute('d',path);p.setAttribute('stroke','#6c98bf');p.setAttribute('stroke-width','2.5');p.setAttribute('fill','none');svg.append(p);b.append(svg);
const [tt,tb]=makeTable(['日期','阶段','排名','5日超额','关注度']);arr.slice().reverse().forEach(v=>{const tr=el('tr');[v.date,v.stage,v.rank??'—',pct(v.rs5),ratio(v.attention)].forEach(t=>td(tr,t));tb.append(tr)});const scroll=el('div',undefined,'scroll');scroll.append(tt);b.append(scroll);
for(const [title,items] of [['近5日领涨股',h?.leaders],['潜在补涨观察（非买点）',h?.laggard_watch]]){b.append(el('h3',title));if(!items?.length){b.append(el('p','暂无符合条件或数据不足','sub'));continue}const [t,body]=makeTable(['公司','5日涨幅','20日涨幅','5日超额','成交额比']);items.forEach(v=>{const tr=el('tr');[v.name+' '+v.code,pct(v.r5),pct(v.r20),pct(v.rs5),ratio(v.amount_ratio)].forEach(z=>td(tr,z));body.append(tr)});const sc=el('div',undefined,'scroll');sc.append(t);b.append(sc)}
$('detail').showModal()}
function board(title,items,get){const section=el('section',undefined,'panel');section.append(el('h2',title));const grid=el('div',undefined,'cards');if(!items.length)grid.append(el('p','暂无符合条件行业','empty'));items.forEach(x=>{const b=el('button',undefined,'item');b.append(el('strong',x.name),el('div',get(x),'metric'),el('small','5日 '+pct(x.r5)+' · '+x.stage,'sub'));b.onclick=()=>detail(x);grid.append(b)});section.append(grid);return section}
function render(){let a=D.levels[level];$('l1').classList.toggle('active',level==='L1');$('l2').classList.toggle('active',level==='L2');const h=D.breadth_health;$('health').textContent='行业 '+a.length+' · 广度有效 '+a.filter(x=>x.breadth).length+' · 成分覆盖 '+(h.members??'—')+'/'+(h.eligible??'—')+(h.status!=='ok'?' · '+(h.reason||'数据不足'):'');
$('summary').replaceChildren(board('量价前兆观察',a.filter(x=>x.flags.includes('量价前兆')).sort((x,y)=>y.attention-x.attention),x=>ratio(x.attention)),board('成交关注度前五',a.slice().sort((x,y)=>y.attention-x.attention).slice(0,5),x=>ratio(x.attention)),board('排名跃升前五',a.slice().filter(x=>x.rank_move!=null).sort((x,y)=>y.rank_move-x.rank_move).slice(0,5),x=>pp(x.rank_move)));
let q=$('query').value.trim(),f=$('flag').value,s=$('stage').value,sort=$('sort').value;
a=a.filter(x=>(!q||x.name.includes(q)||x.code.includes(q))&&(!f||x.flags.includes(f))&&(!s||x.stage===s));
a.sort((x,y)=>sort==='rank'?x.rank-y.rank:sort==='attention'?y.attention-x.attention:sort==='move'?ord(y.rank_move)-ord(x.rank_move):ord(y.breadth?.breadth_change)-ord(x.breadth?.breadth_change));
const [t,b]=makeTable(['行业','阶段/标记','5日涨幅','5日超额','20日涨幅','关注度','排名变化','上涨占比','广度变化']);
a.forEach(x=>{const tr=el('tr'),c=el('td'),btn=el('button',x.name+' #'+x.rank);btn.onclick=()=>detail(x);c.append(btn);tr.append(c);const tags=el('td',x.stage);x.flags.forEach(f=>tags.append(el('span',f,'tag')));tr.append(tags);td(tr,pct(x.r5),x.r5>0?'up':'down');td(tr,pct(x.rs5));td(tr,pct(x.r20));td(tr,ratio(x.attention));td(tr,pp(x.rank_move));td(tr,pct(x.breadth?.rising5,false));td(tr,pp(x.breadth?.breadth_change));b.append(tr)});$('table').replaceChildren(t);if(!a.length)$('table').append(el('p','暂无符合筛选条件的行业','empty'))}
$('asof').textContent='行情日期 '+D.asof+' · 北京时间'+(D.asof!==D.requested_end?' · 非请求日期，检查是否为最新交易日':'');$('l1').onclick=()=>{level='L1';render()};$('l2').onclick=()=>{level='L2';render()};$('close').onclick=()=>$('detail').close();['sort','flag','stage','query'].forEach(id=>$(id).addEventListener(id==='query'?'input':'change',render));render();
</script></body></html>'''
    path.write_text(template.replace("__PAYLOAD__",payload),encoding="utf-8")
